window.BOOK={"key":"rajab","app":"mutoon","lsk":"mutoon_rajab_v1","title":"زوائد ابن رجب","unitWord":"حديث","sub":"تتمة الخمسين على الأربعين النووية · الحديث · الحافظ ابن رجب الحنبلي (ت ٧٩٥هـ) · ٨ حديثًا","source":"https://ketabonline.com/ar/books/97115 (= المكتبة الشاملة: الأربعون النووية مع زيادات ابن رجب، تحقيق الشربيني بن فايق الشربيني، مراجعة مصطفى العدوي؛ مشكول) ص ٦٠–٦٧ · قوبل بـ: جامع العلوم والحكم لابن رجب: ط. دار السلام بضبط ماهر الفحل (OpenITI Shamela0010443)، ط. الرسالة بتحقيق الأرناؤوط (OpenITI Shamela0004268)، ط. دار المعرفة (OpenITI ShamAY0033527)؛ وفتح القوي المتين للعباد (ketabonline 836). مقابلة آلية كلمة بكلمة؛ وشكل الكلمات المعدّلة من sunnah.com. انظر rajab-sources.md","note":"النص المشكول من نشرة الشربيني، وقوبل آليًّا كلمة بكلمة بمتون الأحاديث في «جامع العلوم والحكم» (ط. الفحل، ط. الأرناؤوط، ط. دار المعرفة) وبفتح القوي المتين للعباد، فاعتُمد لفظ جامع العلوم والحكم حيث خالفه الأساس (٤٣، ٤٥، ٤٦، ٤٨ والتخريج)، وأُخذ شكل الكلمات المعدّلة من روايات مشكولة على sunnah.com؛ التفاصيل في تقرير المصادر.","chapters":[{"id":"ra1","title":"زيادات ابن رجب الحنبلي","units":[{"id":"ra1_1","label":"الحديث ٤٣","segs":[["rawi","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"],["matn","«أَلْحِقُوا الْفَرَائِضَ بِأَهْلِهَا، فَمَا أَبْقَتِ الْفَرَائِضُ، فَلِأَوْلَى رَجُلٍ ذَكَرٍ»."],["takh","خَرَّجَهُ الْبُخَارِيُّ وَمُسْلِمٌ."]]},{"id":"ra1_2","label":"الحديث ٤٤","segs":[["rawi","عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«الرَّضَاعَةُ تُحَرِّمُ مَا تُحَرِّمُ الْوِلَادَةُ»."],["takh","خَرَّجَهُ الْبُخَارِيُّ وَمُسْلِمٌ."]]},{"id":"ra1_3","label":"الحديث ٤٥ · المقطع ١ من ٢","segs":[["rawi","عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ وَهُوَ بِمَكَّةَ يَقُولُ:"],["matn","«إِنَّ اللَّهَ وَرَسُولَهُ حَرَّمَ بَيْعَ الْخَمْرِ وَالْمَيْتَةِ وَالْخِنْزِيرِ وَالْأَصْنَامِ». فَقِيلَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ شُحُومَ الْمَيْتَةِ، فَإِنَّهُ يُطْلَى بِهَا السُّفُنُ، وَيُدْهَنُ بِهَا الْجُلُودُ، وَيَسْتَصْبِحُ بِهَا النَّاسُ؟ قَالَ: «لَا، هُوَ حَرَامٌ»،"]]},{"id":"ra1_4","label":"الحديث ٤٥ · المقطع ٢ من ٢","segs":[["matn","ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: «قَاتَلَ اللَّهُ الْيَهُودَ، إِنَّ اللَّهَ حَرَّمَ عَلَيْهِمُ الشُّحُومَ، فَأَجْمَلُوهُ، ثُمَّ بَاعُوهُ، فَأَكَلُوا ثَمَنَهُ»."],["takh","خَرَّجَهُ الْبُخَارِيُّ وَمُسْلِمٌ."]]},{"id":"ra1_5","label":"الحديث ٤٦","segs":[["rawi","عَنْ أَبِي بُرْدَةَ، عَنْ أَبِيهِ، عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ"],["matn","أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَهُ إِلَى الْيَمَنِ، فَسَأَلَهُ عَنْ أَشْرِبَةٍ تُصْنَعُ بِهَا، فَقَالَ: «وَمَا هِيَ؟» قَالَ: الْبِتْعُ وَالْمِزْرُ، فَقِيلَ لِأَبِي بُرْدَةَ: وَمَا الْبِتْعُ؟ قَالَ: نَبِيذُ الْعَسَلِ، وَالْمِزْرُ نَبِيذُ الشَّعِيرِ، فَقَالَ: «كُلُّ مُسْكِرٍ حَرَامٌ»."],["takh","خَرَّجَهُ الْبُخَارِيُّ."]]},{"id":"ra1_6","label":"الحديث ٤٧","segs":[["rawi","عَنِ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:"],["matn","«مَا مَلَأَ آدَمِيٌّ وِعَاءً شَرًّا مِنْ بَطْنٍ، بِحَسْبِ ابْنِ آدَمَ أَكَلَاتٌ يُقِمْنَ صُلْبَهُ، فَإِنْ كَانَ لَا مَحَالَةَ، فَثُلُثٌ لِطَعَامِهِ، وَثُلُثٌ لِشَرَابِهِ، وَثُلُثٌ لِنَفَسِهِ»."],["takh","رَوَاهُ الْإِمَامُ أَحْمَدُ وَالتِّرْمِذِيُّ وَالنَّسَائِيُّ وَابْنُ مَاجَهْ، وَقَالَ التِّرْمِذِيُّ: حَدِيثٌ حَسَنٌ."]]},{"id":"ra1_7","label":"الحديث ٤٨","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ:"],["matn","«أَرْبَعٌ مَنْ كُنَّ فِيهِ كَانَ مُنَافِقًا، وَمَنْ كَانَتْ خَصْلَةٌ مِنْهُنَّ فِيهِ كَانَتْ فِيهِ خَصْلَةٌ مِنَ النِّفَاقِ حَتَّى يَدَعَهَا: مَنْ إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا خَاصَمَ فَجَرَ، وَإِذَا عَاهَدَ غَدَرَ»."],["takh","خَرَّجَهُ الْبُخَارِيُّ وَمُسْلِمٌ."]]},{"id":"ra1_8","label":"الحديث ٤٩","segs":[["rawi","عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:"],["matn","«لَوْ أَنَّكُمْ تَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ، لَرَزَقَكُمْ كَمَا يَرْزُقُ الطَّيْرَ، تَغْدُو خِمَاصًا، وَتَرُوحُ بِطَانًا»."],["takh","رَوَاهُ الْإِمَامُ أَحْمَدُ وَالتِّرْمِذِيُّ وَالنَّسَائِيُّ وَابْنُ مَاجَهْ وَابْنُ حِبَّانَ فِي «صَحِيحِهِ» وَالْحَاكِمُ، وَقَالَ التِّرْمِذِيُّ: حَسَنٌ صَحِيحٌ."]]},{"id":"ra1_9","label":"الحديث ٥٠","segs":[["rawi","عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ قَالَ:"],["matn","أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ، فَقَالَ: يَا رَسُولَ اللَّهِ إِنَّ شَرَائِعَ الْإِسْلَامِ قَدْ كَثُرَتْ عَلَيْنَا، فَبَابٌ نَتَمَسَّكُ بِهِ جَامِعٌ؟ قَالَ: «لَا يَزَالُ لِسَانُكَ رَطْبًا مِنْ ذِكْرِ اللَّهِ عَزَّ وَجَلَّ»."],["takh","خَرَّجَهُ الْإِمَامُ أَحْمَدُ بِهَذَا اللَّفْظِ."]]}]}],"sharh":false};
